const D = { energy: .6, scale: 1, speed: 1, density: .4, tilt: .55, grain: .45, hue: 194, x: .5, y: .5, style: 'sem', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Kardar-Parisi-Zhang growing interface, by ballistic deposition seen in
// cross-section. Vapour arrives along a ray and sticks to the FIRST material it
// touches -- including sideways contact -- so tips capture flux, shadow their
// neighbours and the front roughens into the self-affine KPZ interface while
// the buried film keeps the record: columnar voids, overhangs, strata.
//
// Perpetual by construction: the film never stops growing. Once the mean front
// climbs past 45% of the frame the buffer scrolls, so the substrate runs off the
// bottom forever and the view tracks the front. On top of that the beam's angle
// of incidence swings on three incommensurate K.t rates -- glancing-angle
// deposition -- so the columns tilt, then chevron, then bunch, and no two
// stretches of film are alike.
// ---------------------------------------------------------------------------
const BW = 200, BH = Math.max(100, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.occ = new Uint8Array(N); S.hcol = new Int32Array(BW);
  S.dns = new Float32Array(N); S.tmp = new Float32Array(N); S.blr = new Float32Array(N);
  S.init = false; S.seedUsed = null;
}

const sd = P.seed | 0;
function hs3(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
let RR = 0, GG = 0, BB = 0;
function hsv(h, s, v) {
  h = h - Math.floor(h);
  const i = Math.floor(h * 6), f = h * 6 - i, p = v * (1 - s), q = v * (1 - f * s), w = v * (1 - (1 - f) * s);
  if (i === 0) { RR = v; GG = w; BB = p; } else if (i === 1) { RR = q; GG = v; BB = p; }
  else if (i === 2) { RR = p; GG = v; BB = w; } else if (i === 3) { RR = p; GG = q; BB = v; }
  else if (i === 4) { RR = w; GG = p; BB = v; } else { RR = v; GG = p; BB = q; }
}
function rnd() { let x = S.rng; x ^= x << 13; x |= 0; x ^= x >>> 17; x ^= x << 5; x |= 0; S.rng = x; return (x >>> 0) / 4294967296; }

const occ = S.occ, hcol = S.hcol, dns = S.dns, tmp = S.tmp, blr = S.blr;

// ---- seed-deterministic restart: bare substrate ----
if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  S.rng = (sd * 2654435761 + 0x9e3779b9) | 0; if (S.rng === 0) S.rng = 1;
  occ.fill(0);
  const base = BH - 6;
  for (let i = 0; i < BW; i++) {
    const h0 = base - ((hs3(i, 7, 3) * 2) | 0);
    for (let j = h0; j < BH; j++) occ[j * BW + i] = 1;
    hcol[i] = h0;
  }
  S.scrolled = 0; S.thick = 0;
}

const tt = K.t;

// ---- glancing-angle deposition: the beam swings on incommensurate rates ----
const tamp = P.tilt * 1.30;
const th0 = tamp * (0.55 * Math.sin(tt * 0.037) + 0.30 * Math.sin(tt * 0.091 + 1.3) + 0.15 * Math.sin(tt * 0.163 + 0.7));
const spread = 0.06 + P.density * 2.1;          // diffuse flux packs dense; collimated -> porous columns

// mean front height -> film thickness bookkeeping
let hs = 0;
for (let i = 0; i < BW; i++) hs += hcol[i];
let meanTop = hs / BW;
S.thick = S.scrolled + (BH - meanTop);
const band = 1 + ((S.thick * (0.09 + P.grain * 0.10) * 200) % 200 | 0);

// ---- deposit ----
const flux = Math.max(6, Math.round((14 + P.speed * 46) * (0.8 + K.swell * 0.25 + A.rms * 0.5)));
let top = BH;
for (let i = 0; i < BW; i++) if (hcol[i] < top) top = hcol[i];
for (let q = 0; q < flux; q++) {
  const th = th0 + (rnd() - 0.5) * spread;
  const sxd = Math.sin(th), syd = Math.cos(th);
  if (syd < 0.05) continue;
  let x = rnd() * BW, y = top - 2; if (y < 0) y = 0;
  let prev = -1, stuck = -1;
  for (let s = 0; s < 900; s++) {
    x += sxd * 0.5; y += syd * 0.5;
    const iy = y | 0;
    if (iy >= BH - 1) { let ix = Math.floor(x) % BW; if (ix < 0) ix += BW; stuck = (BH - 1) * BW + ix; break; }
    if (iy < 0) { if (y < -4) break; continue; }
    let ix = Math.floor(x) % BW; if (ix < 0) ix += BW;
    const p = iy * BW + ix;
    if (occ[p]) { stuck = prev; break; }                       // head-on: settle in the last free cell
    const l = occ[iy * BW + (ix > 0 ? ix - 1 : BW - 1)], r2 = occ[iy * BW + (ix < BW - 1 ? ix + 1 : 0)];
    const u = iy > 0 ? occ[(iy - 1) * BW + ix] : 0, dn = occ[(iy + 1) * BW + ix];
    if (l || r2 || u || dn) { stuck = p; break; }              // lateral capture -> overhangs, voids, KPZ
    prev = p;
  }
  if (stuck >= 0) {
    occ[stuck] = band;
    const si = stuck % BW, sj = (stuck / BW) | 0;
    if (sj < hcol[si]) hcol[si] = sj;
  }
}

// ---- scroll so the front stays put and the substrate runs off the bottom ----
hs = 0; for (let i = 0; i < BW; i++) hs += hcol[i];
meanTop = hs / BW;
let sc = 0;
while (meanTop < BH * 0.45 && sc < 6) { sc++; meanTop += 1; }
if (sc > 0) {
  occ.copyWithin(sc * BW, 0, (BH - sc) * BW);
  occ.fill(0, 0, sc * BW);
  for (let i = 0; i < BW; i++) { const v = hcol[i] + sc; hcol[i] = v > BH - 1 ? BH - 1 : v; }
  S.scrolled += sc;
}

// ---- relief: blur the occupancy and shade off its gradient ----
for (let p = 0; p < N; p++) dns[p] = occ[p] ? 1 : 0;
{
  const R = 1, inv = 1 / (2 * R + 1), lastW = BW - 1, lastH = BH - 1;
  for (let j = 0; j < BH; j++) {
    const jc = j * BW;
    let sum = dns[jc] * (R + 1);
    for (let k = 1; k <= R; k++) sum += dns[jc + (k > lastW ? lastW : k)];
    for (let i = 0; i < BW; i++) {
      tmp[jc + i] = sum * inv;
      const a = i + R + 1, b = i - R;
      sum += dns[jc + (a > lastW ? lastW : a)] - dns[jc + (b < 0 ? 0 : b)];
    }
  }
  for (let i = 0; i < BW; i++) {
    let sum = tmp[i] * (R + 1);
    for (let k = 1; k <= R; k++) sum += tmp[(k > lastH ? lastH : k) * BW + i];
    for (let j = 0; j < BH; j++) {
      blr[j * BW + i] = sum * inv;
      const a = j + R + 1, b = j - R;
      sum += tmp[(a > lastH ? lastH : a) * BW + i] - tmp[(b < 0 ? 0 : b) * BW + i];
    }
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const style = P.style;
const hb = P.hue / 360 + (K.section | 0) * 0.025 + Math.sin(tt * 0.017) * 0.02;
const gain = 0.45 + P.energy * 1.05 + A.rms * 0.3;
const gr = P.grain;
for (let j = 0; j < BH; j++) {
  const jc = j * BW;
  const jm = (j > 0 ? j - 1 : 0) * BW, jp2 = (j < BH - 1 ? j + 1 : BH - 1) * BW;
  for (let i = 0; i < BW; i++) {
    const p = jc + i;
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    const v = occ[p];
    const gx = blr[jc + ip] - blr[jc + im], gy = blr[jp2 + i] - blr[jm + i];
    const lit = Math.max(0, -gx * 0.55 - gy * 0.83) * 1.5;     // raking light from the upper left
    const bandv = v ? (v - 1) / 200 : 0;
    const dh = hcol[i] - j;
    const fresh = v ? Math.max(0, 1 - Math.abs(dh) * 0.16) : 0;     // latent glow at the growth front
    const vac = !v && j < hcol[i] - 1 ? 1 : 0;                       // vapour above the front
    const th = (hs3(i, j, 51) - 0.5) * 0.10 * gr;
    let r, gg, b;
    if (style === 'strata') {
      // the film as stratigraphy: deposition-time colour bands through the columns
      if (v) {
        hsv(hb + bandv * 0.62, 0.44 + 0.22 * Math.sin(bandv * 25.1), 1);
        const sh = (0.34 + blr[p] * 0.34 + lit * 0.5) * (0.6 + gain * 0.55);
        r = RR * sh + fresh * 0.30; gg = GG * sh + fresh * 0.30; b = BB * sh + fresh * 0.32;
      } else { const a2 = vac ? 0.15 : 0.05; r = a2 * 0.8; gg = a2 * 0.9; b = a2 * 1.4; }
    } else if (style === 'xray') {
      // absorption radiograph: dense film dark, voids and vapour bright
      const dsty = blr[p];
      const t2 = 0.80 - dsty * 0.70 * (0.55 + gain * 0.5);
      r = t2 * 0.93; gg = t2 * 0.96; b = t2 * 1.0;
      r -= fresh * 0.10; gg -= fresh * 0.07; b -= fresh * 0.02;
    } else if (style === 'schematic') {
      // blueprint: the void network and the front profile, nothing else
      const edge = Math.min(1, Math.sqrt(gx * gx + gy * gy) * 2.6);
      const base = 0.06 + (v ? 0.03 : 0);
      const fl = Math.max(0, 1 - Math.abs(dh) * 0.55);
      r = base * 0.5 + edge * 0.42 * gain + fl * 0.30;
      gg = base * 0.9 + edge * 0.80 * gain + fl * 0.55;
      b = base * 1.9 + edge * 1.0 * gain + fl * 0.72;
    } else {
      // sem (default): greyscale cross-section, relief-shaded columns, black voids
      if (v) {
        const base = (0.26 + blr[p] * 0.30 + lit * 0.62) * (0.6 + gain * 0.5);
        hsv(hb, 0.10, 1);
        r = RR * base; gg = GG * base; b = BB * base;
        hsv(hb + 0.5, 0.5, 1);
